module adder_4bit_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] Sum,
    input logic       Cout
);

    // Sum and Cout must match 4-bit addition with carry in.
    check_overall_addition: assert property (
        @(posedge clk)
        {Cout, Sum} == ({1'b0, A} + {1'b0, B} + {4'b0, Cin})
    );

    // Bit 0 sum must be the XOR of A[0], B[0], and Cin.
    check_sum_bit0: assert property (
        @(posedge clk)
        Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit 1 sum must use the carry generated by bit 0.
    check_sum_bit1: assert property (
        @(posedge clk)
        Sum[1] == (
            A[1] ^ B[1] ^
            ((A[0] & B[0]) | ((A[0] ^ B[0]) & Cin))
        )
    );

    // Bit 2 sum must use the ripple carry generated through bit 1.
    check_sum_bit2: assert property (
        @(posedge clk)
        Sum[2] == (
            A[2] ^ B[2] ^
            (
                (A[1] & B[1]) |
                (
                    (A[1] ^ B[1]) &
                    (
                        (A[0] & B[0]) |
                        ((A[0] ^ B[0]) & Cin)
                    )
                )
            )
        )
    );

    // Bit 3 sum must use the ripple carry generated through bit 2.
    check_sum_bit3: assert property (
        @(posedge clk)
        Sum[3] == (
            A[3] ^ B[3] ^
            (
                (A[2] & B[2]) |
                (
                    (A[2] ^ B[2]) &
                    (
                        (A[1] & B[1]) |
                        (
                            (A[1] ^ B[1]) &
                            (
                                (A[0] & B[0]) |
                                ((A[0] ^ B[0]) & Cin)
                            )
                        )
                    )
                )
            )
        )
    );

    // Cout must be the final ripple carry from the most significant stage.
    check_cout_equation: assert property (
        @(posedge clk)
        Cout == (
            (A[3] & B[3]) |
            (
                (A[3] ^ B[3]) &
                (
                    (A[2] & B[2]) |
                    (
                        (A[2] ^ B[2]) &
                        (
                            (A[1] & B[1]) |
                            (
                                (A[1] ^ B[1]) &
                                (
                                    (A[0] & B[0]) |
                                    ((A[0] ^ B[0]) & Cin)
                                )
                            )
                        )
                    )
                )
            )
        )
    );

endmodule